<script>
window.addEventListener('DOMContentLoaded', function(){

  function measureWidth(el){
    var s = el.style;
    var po = s.overflow, pw = s.width;
    s.overflow = 'visible'; s.width = 'auto';
    var w = el.scrollWidth + 28;
    s.overflow = po; s.width = pw || '0';
    return w;
  }

  var w1 = measureWidth(document.getElementById('line1'));
  var w2 = measureWidth(document.getElementById('line2'));
  var wh = measureWidth(document.getElementById('history'));
