  /* bottom rule */
    .to('#rule-bot', { width:wr,  duration:0.4,  ease:'power2.out' }, 3.8)

  /* history typewriter */
    .to('#history',  { width:wh,  duration:1.1,  ease:'none' },       4.4)

  /* ── HOLD briefly ── */

  /* ── EXIT: erase then fade to black ── */
    .to('#history',  { width:0,   duration:0.6,  ease:'none' },       6.4)
    .to(['#rule-top','#rule-bot'], { width:0, duration:0.35, ease:'power2.in' }, 6.7)
    .to(['#line1','#line2'],       { width:0, duration:0.55, ease:'none' },      6.75)

  /* fade to black — completes exactly at 9s */
    .to('#fade',     { opacity:1, duration:1.4,  ease:'power2.inOut' }, 7.5);
});
