html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  font-size: 10px; /* 1rem = 10px for easy rem usage */
}
body {
  background: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

/* ── exact .demo replication ── */
.demo {
  position: relative;
  left: 0; top: 0;
  width: 32rem;
  height: 47rem;
  perspective: 1000px;
  transform-style: preserve-3d;
  animation: rotateReverse 3s infinite linear;
}

.demo__content {
  position: relative;
  height: 100%;
  transform-style: preserve-3d;
  animation: rotate 3s infinite linear;
  transform: rotateX(10deg) rotateZ(0);
  background: #fff;
  border-radius: 4px;
}

.demo__content:before {
  content: "";
  z-index: -1;
  position: absolute;
  left: 0; top: 0;
  width: 100%; height: 100%;
  box-shadow: 0 5rem 10rem rgba(0,0,0,0.55);
  border-radius: 4px;
}

.demo__img {
  overflow: hidden;
  position: absolute;
  left: -0.55rem;
  top: -0.35rem;
  width: calc(100% + 1.1rem);
  height: calc(100% + 0.7rem);
  transform: translateZ(5rem) scale(0.95);
  border-radius: 3px;
}

.demo__img img {
  position: absolute;
  left: 0; top: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  object-position: center top;
  display: block;
  filter: grayscale(8%) contrast(1.06);
}

.demo__img:after {
  content: "";
  z-index: 2;
  overflow: hidden;
  position: absolute;
  left: -20%; top: 0;
  width: 80%;
  padding-bottom: 80%;
  border-radius: 50%;
  background: radial-gradient(ellipse farthest-corner at center,
    rgba(255,255,255,0.22) 0%,
    rgba(255,255,255,0) 100%);
  transform: translateY(-100%);
  animation: shiny 3s infinite ease-in-out;
}

/* exact 4-waypoint shiny path from original */
@keyframes shiny {
  0%   { transform: translateY(-100%); }
  25%  { transform: translateY(-100%); }
  50%  { transform: translateY(500px); }
  50.1%{ transform: translate(75%, 500px); }
  75%  { transform: translate(75%, -100%); }
  100% { transform: translateY(-100%); }
}

@keyframes rotate {
  0%   { transform: rotateX(10deg) rotateZ(0deg); }
  100% { transform: rotateX(10deg) rotateZ(360deg); }
}

@keyframes rotateReverse {
  0%   { transform: rotateZ(0deg); }
  100% { transform: rotateZ(-360deg); }
}

/* ── label ── */
#label {
  position: absolute;
  bottom: 52px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}
#label .name {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 4.8rem;
  font-weight: 700;
  color: #f0ece4;
  line-height: .90;
  letter-spacing: -.01em;
