    &:before {
      content: "";
      z-index: -1;
      position: absolute;
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      box-shadow: 0 5rem 10rem rgba(0,0,0,0.4);
    }
  }
  &__img {
    overflow: hidden;
    position: absolute;
    left: ($w - $imgW)/2;
    top: ($h - $imgH)/2;
    width: $imgW;
    height: $imgH;
    transform: translateZ(5rem) scale(0.95);
    &:before {
      content: "";
      position: absolute;
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      background-image: url('https://s3-us-west-2.amazonaws.com/s.cdpn.io/142996/macbeth.png');
      background-size: cover;
