      content: "";
      z-index: 2;
      overflow: hidden;
      position: absolute;
      left: -20%;
      top: 0;
      width: 80%;
      padding-bottom: 80%;
      border-radius: 50%;
      background: radial-gradient(ellipse farthest-corner at center, rgba(255,255,255,0.20) 0%, rgba(255,255,255,0) 100%);
      transform: translateY(-100%);
      animation: shiny $animTime infinite ease-in-out;
    }
  }
}
@keyframes rotate {
  100% {
    transform: rotateX(10deg) rotateZ(360deg);
  }
}
@keyframes rotateReverse {
  100% {
    transform: rotateZ(-360deg);
  }
}
@keyframes shiny {
  25% {
    transform: translateY(-100%);
  }
  50% {
    transform: translateY($h);
  }
  50.1% {
    transform: translate(75%, $h);
  }
  75% {
    transform: translate(75%, -100%);
  }
}
.source {
  position: absolute;
  left: 0.5rem;
  bottom: 0.5rem;
  font-size: 2rem;
}
.tip {
  padding: 1rem;
  font-size: 1.8rem;
